SELECT 
FROM baseline_rule
WHERE enabled = 1
  AND status = 'PUBLISHED'
  AND id IN

      #{id}

ORDER BY FIELD(id,

      #{id}

)

SELECT DISTINCT br.id, br.rule_code, br.rule_name, br.category, br.description, br.severity, br.score, br.level, br.asset_type, bat.type_code AS asset_type_code, br.os_type, br.check_method, br.check_script, br.remediation_type, br.remediation_script, br.version, br.is_mandatory, br.enabled, br.status, br.protection_level_flag, br.group_combine_logic, br.create_time, br.update_time FROM baseline_rule br JOIN baseline_rule_asset_ref ref ON ref.rule_id = br.id JOIN baseline_asset_type bat ON bat.id = ref.asset_type_id WHERE br.enabled = 1 AND br.status = 'PUBLISHED' AND br.id IN
#{id}
AND bat.enabled = 1 AND bat.type_code IN
#{assetTypeCode}
ORDER BY FIELD(br.id,
#{id}
)

SELECT FROM baseline_rule_item WHERE rule_id IN
#{ruleId}
ORDER BY rule_id ASC, item_order ASC, id ASC

SELECT FROM baseline_rule_item WHERE rule_id IN
#{ruleId}
AND check_key IN
#{checkKey}
AND (protection_level_id IS NULL OR protection_level_id = #{protectionLevelId})
ORDER BY rule_id ASC, CASE WHEN protection_level_id = #{protectionLevelId} THEN 0 ELSE 1 END, item_order ASC, id ASC

sql.if:
AND (
    EXISTS (
        SELECT 1
        FROM baseline_rule_asset_ref ref
        JOIN baseline_asset_type bat ON bat.id = ref.asset_type_id
        WHERE ref.rule_id = br.id
          AND bat.enabled = 1
          AND UPPER(bat.type_code) = #{assetTypeCode}
    )
    OR UPPER(COALESCE(br.asset_type, br.os_type, '')) = #{assetTypeCode}
)

mapper.update:
UPDATE baseline_rule
SET enabled = #{enabled}
WHERE id = #{id}
